//! The Rust twin of `glance.privacy.redact` (secret detection, placeholder shielding) and
//! `glance.privacy.entities` (protected spans).
//!
//! The Python modules are the specification: every pattern here reproduces Python `re`
//! semantics exactly, including what Rust's `regex` cannot say directly:
//!
//! * `\w`, `\s`, `\d`, `\b` are Python's (str methods of the Unicode version in
//!   [`tables::UNICODE_VERSION`]), not Rust's Unicode classes; the tables are generated by
//!   `scripts/gen-privacy-tables.py`.
//! * Look-behinds (`(?<!…)`, `\b` before a word character) are checked on the match start;
//!   a failed check retries one character later, as Python's scanner does.
//! * `re.IGNORECASE` keywords spell out every code point Python lets each letter match
//!   (`ı` and `İ` match `i`, `ſ` matches `s`, `K` matches `k`).
//! * Entropy sums its terms the way the running Python's `sum()` does (plain before 3.12,
//!   Neumaier-compensated since), so a token on a threshold decides the same way.
//!
//! Spans are computed on UTF-8 byte offsets and returned as code-point (Python str) indices.

#[rustfmt::skip]
pub mod tables;

use std::cmp::Ordering as CmpOrdering;
use std::fmt::Write as _;
use std::sync::LazyLock;
use std::sync::atomic::{AtomicBool, Ordering};

use regex::Regex;

/// Python 3.12+ `sum()` of floats is compensated; set once from the interpreter's version.
pub static COMPENSATED_SUM: AtomicBool = AtomicBool::new(false);

/// Half-open `[start, end)` range with its kind.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Span {
    pub start: usize,
    pub end: usize,
    pub kind: &'static str,
}

/// A shielded text: see `glance.privacy.redact.Shielded` (offsets are code points).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Shielded {
    pub text: String,
    pub mapping: Vec<(String, String)>,
    pub has_objects: bool,
    /// (shielded_start, shielded_end, original_start, original_end, is_placeholder)
    pub segments: Vec<(usize, usize, usize, usize, bool)>,
}

pub const OBJECT: char = '\u{FFFC}';
const ZWJ: char = '\u{200D}';
const PLACEHOLDER_OPEN: &str = "[[GLANCE_";

// ---- character classes -------------------------------------------------------------------

fn in_ranges(t: &[(u32, u32)], c: char) -> bool {
    let c = c as u32;
    t.binary_search_by(|&(a, b)| {
        if b < c {
            CmpOrdering::Less
        } else if a > c {
            CmpOrdering::Greater
        } else {
            CmpOrdering::Equal
        }
    })
    .is_ok()
}

/// Python `re` `\w`.
pub fn is_word(c: char) -> bool {
    in_ranges(tables::WORD, c)
}

fn decimal_value(c: char) -> Option<u32> {
    let c = c as u32;
    tables::DECIMAL
        .binary_search_by(|&(a, b, _)| {
            if b < c {
                CmpOrdering::Less
            } else if a > c {
                CmpOrdering::Greater
            } else {
                CmpOrdering::Equal
            }
        })
        .ok()
        .map(|i| tables::DECIMAL[i].2 + (c - tables::DECIMAL[i].0))
}

fn is_emoji(c: char) -> bool {
    in_ranges(tables::EMOJI, c)
}

fn is_emoji_joiner(c: char) -> bool {
    matches!(c, ZWJ | '\u{FE0F}' | '\u{20E3}') || ('\u{E0020}'..='\u{E007F}').contains(&c)
}

/// A regex character class from code-point ranges plus `extra` (already escaped).
fn class(t: &[(u32, u32)], extra: &str, negate: bool) -> String {
    let mut s = String::from(if negate { "[^" } else { "[" });
    for &(a, b) in t {
        let _ = write!(s, "\\x{{{a:X}}}");
        if b > a {
            let _ = write!(s, "-\\x{{{b:X}}}");
        }
    }
    s.push_str(extra);
    s.push(']');
    s
}

fn decimal_class() -> String {
    let r: Vec<(u32, u32)> = tables::DECIMAL.iter().map(|&(a, b, _)| (a, b)).collect();
    class(&r, "", false)
}

/// `word` under Python `re.IGNORECASE`, one class per letter.
fn ignorecase(word: &str) -> String {
    word.chars()
        .map(|l| {
            let (_, cps) = tables::IGNORECASE
                .iter()
                .find(|(k, _)| *k == l)
                .expect("letter missing from tables::IGNORECASE");
            let mut s = String::from("[");
            for cp in *cps {
                let _ = write!(s, "\\x{{{cp:X}}}");
            }
            s.push(']');
            s
        })
        .collect()
}

fn prev_char(text: &str, pos: usize) -> Option<char> {
    text[..pos].chars().next_back()
}

/// Python's `\b` before a word character / `(?<!\w)`: no word character just before.
fn no_word_before(text: &str, pos: usize) -> bool {
    !prev_char(text, pos).is_some_and(is_word)
}

fn next_char_len(text: &str, pos: usize) -> usize {
    text[pos..].chars().next().map_or(1, char::len_utf8)
}

/// `finditer` for a pattern whose look-behind `ok(start)` the regex could not express.
fn find_where(re: &Regex, text: &str, ok: impl Fn(usize) -> bool) -> Vec<(usize, usize)> {
    let mut out = Vec::new();
    let mut at = 0;
    while at <= text.len() {
        let Some(m) = re.find_at(text, at) else { break };
        if ok(m.start()) {
            out.push((m.start(), m.end()));
            at = if m.end() > m.start() {
                m.end()
            } else {
                m.end() + next_char_len(text, m.end())
            };
        } else {
            at = m.start() + next_char_len(text, m.start());
        }
    }
    out
}

// ---- patterns ----------------------------------------------------------------------------

static SPACE: LazyLock<String> = LazyLock::new(|| class(tables::SPACE, "", false));
static NOT_SPACE: LazyLock<String> = LazyLock::new(|| class(tables::SPACE, "", true));

/// `_API_KEY` without its look-behind `(?<![A-Za-z0-9_-])` (first branch) and `\b` (Bearer).
static API_KEY: LazyLock<Regex> = LazyLock::new(|| {
    let pat = format!(
        concat!(
            r"(?:sk-[A-Za-z0-9_-]{{20,}}|gh[pos]_[A-Za-z0-9]{{20,}}|github_",
            r"pat_[A-Za-z0-9_]{{20,}}",
            r"|AKIA[0-9A-Z]{{16}}|xox[abprs]-[A-Za-z0-9-]{{10,}}|AIza[0-9A-Za-z_-]{{35}}",
            r"|(?:sk|rk|pk)_(?:live|test)_[A-Za-z0-9]{{16,}}|glpat-[A-Za-z0-9_-]{{20,}})",
            r"|Bearer{sp}+{nsp}{{20,}}"
        ),
        sp = *SPACE,
        nsp = *NOT_SPACE
    );
    Regex::new(&pat).expect("API_KEY")
});
static JWT: LazyLock<Regex> = LazyLock::new(|| {
    Regex::new(r"eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+").expect("JWT")
});
static PEM: LazyLock<Regex> = LazyLock::new(|| {
    Regex::new(r"(?s)-----BEGIN [A-Z0-9 ]+-----.*?(?:-----END [A-Z0-9 ]+-----|\z)").expect("PEM")
});
static CARD_RUN: LazyLock<Regex> = LazyLock::new(|| {
    let d = decimal_class();
    Regex::new(&format!(r"{d}(?:[ \t\r\n-]?{d})*")).expect("CARD_RUN")
});
/// `_ASSIGN` without its leading `\b`; groups 1/2/3 are dq/sq/bare.
static ASSIGN: LazyLock<Regex> = LazyLock::new(|| {
    let kw = ["password", "passwd", "pwd", "secret", "token"]
        .iter()
        .map(|w| ignorecase(w))
        .chain([format!("{}[_-]?{}", ignorecase("api"), ignorecase("key"))])
        .collect::<Vec<_>>()
        .join("|");
    let pat = format!(
        r#"(?:{kw}){sp}*[:=]{sp}*(?:"([^"\n]+)"|'([^'\n]+)'|({nsp}+))"#,
        sp = *SPACE,
        nsp = *NOT_SPACE
    );
    Regex::new(&pat).expect("ASSIGN")
});

static CODE: LazyLock<Regex> =
    LazyLock::new(|| Regex::new(r"(?s)```.*?(?:```|\z)|`[^`\n]+`").expect("CODE"));
static URL: LazyLock<Regex> = LazyLock::new(|| {
    Regex::new(&format!(r"https?://{nsp}+|www\.{nsp}+", nsp = *NOT_SPACE)).expect("URL")
});
/// `mention` without the `(?<!\w)` before `@` and `#`.
static MENTION: LazyLock<Regex> = LazyLock::new(|| {
    let w = class(tables::WORD, r".\-", false);
    let wh = class(tables::WORD, r"\-", false);
    Regex::new(&format!(r"@{w}+|<@[^>\n]*>|#{wh}+")).expect("MENTION")
});
static EMOJI_NAME: LazyLock<Regex> =
    LazyLock::new(|| Regex::new(r":[a-z0-9_+-]+:").expect("EMOJI_NAME"));

// ---- code points ---------------------------------------------------------------------------

/// Byte offset -> code-point index for one text.
struct Cp(Option<Vec<u32>>);

impl Cp {
    fn new(text: &str) -> Self {
        if text.is_ascii() {
            return Cp(None);
        }
        let mut v = vec![0u32; text.len() + 1];
        let mut n = 0u32;
        for (b, _) in text.char_indices() {
            v[b] = n;
            n += 1;
        }
        v[text.len()] = n;
        Cp(Some(v))
    }

    fn at(&self, b: usize) -> usize {
        match &self.0 {
            None => b,
            Some(v) => v[b] as usize,
        }
    }

    fn span(&self, s: Span) -> Span {
        Span {
            start: self.at(s.start),
            end: self.at(s.end),
            kind: s.kind,
        }
    }
}

// ---- secrets -------------------------------------------------------------------------------

fn rank(kind: &str) -> u8 {
    match kind {
        "pem" => 0,
        "jwt" => 1,
        "api_key" => 2,
        "assignment" => 3,
        "card" => 4,
        _ => 5, // entropy
    }
}

fn py_sum(terms: impl Iterator<Item = f64>) -> f64 {
    sum_floats(COMPENSATED_SUM.load(Ordering::Relaxed), terms)
}

fn sum_floats(compensated: bool, terms: impl Iterator<Item = f64>) -> f64 {
    if !compensated {
        return terms.fold(0.0, |a, x| a + x);
    }
    // CPython >= 3.12 builtin sum(): Neumaier's improved Kahan-Babuska summation.
    let (mut f, mut c) = (0.0f64, 0.0f64);
    for x in terms {
        let t = f + x;
        if f.abs() >= x.abs() {
            c += (f - t) + x;
        } else {
            c += (x - t) + f;
        }
        f = t;
    }
    if c != 0.0 && c.is_finite() {
        f += c;
    }
    f
}

/// `_entropy` for an ASCII token: terms in first-occurrence order, as `Counter` keeps them.
fn entropy(tok: &[u8]) -> f64 {
    let n = tok.len() as f64;
    let mut counts = [0u32; 256];
    let mut order = Vec::with_capacity(64);
    for &b in tok {
        if counts[b as usize] == 0 {
            order.push(b);
        }
        counts[b as usize] += 1;
    }
    -py_sum(order.iter().map(|&b| {
        let p = counts[b as usize] as f64 / n;
        p * p.log2()
    }))
}

fn char_class(b: u8) -> u8 {
    if b.is_ascii_uppercase() {
        b'u'
    } else if b.is_ascii_lowercase() {
        b'l'
    } else if b.is_ascii_digit() {
        b'd'
    } else {
        b'o'
    }
}

fn class_switches(tok: &[u8]) -> f64 {
    let n = tok
        .windows(2)
        .filter(|w| char_class(w[0]) != char_class(w[1]))
        .count();
    n as f64 / (tok.len() - 1) as f64
}

const SHORT_ENTROPY: f64 = 3.7;
const SHORT_SWITCHES: f64 = 0.5;

/// `_is_entropy_secret` (tokens are ASCII: `_TOKEN` matches only `[A-Za-z0-9+/=_-]`).
fn is_entropy_secret(tok: &[u8]) -> bool {
    let upper = tok.iter().any(u8::is_ascii_uppercase);
    let lower = tok.iter().any(u8::is_ascii_lowercase);
    if !((upper || lower) && tok.iter().any(u8::is_ascii_digit)) {
        return false;
    }
    if tok.contains(&b'/')
        && !tok
            .iter()
            .any(|&c| c.is_ascii_uppercase() || c == b'+' || c == b'=')
    {
        return false;
    }
    let e = entropy(tok);
    let hex = tok
        .iter()
        .all(|&c| c.is_ascii_digit() || (b'a'..=b'f').contains(&c));
    if e >= 4.0 || (tok.len() >= 32 && hex && e >= 3.0) {
        return true;
    }
    e >= SHORT_ENTROPY && class_switches(tok) >= SHORT_SWITCHES && upper && lower
}

fn is_token_byte(b: u8) -> bool {
    b.is_ascii_alphanumeric() || matches!(b, b'+' | b'/' | b'=' | b'_' | b'-')
}

/// `_TOKEN`: maximal runs of `[A-Za-z0-9+/=_-]`, 20 or longer.
fn tokens(text: &str) -> Vec<(usize, usize)> {
    let bytes = text.as_bytes();
    let mut out = Vec::new();
    let mut i = 0;
    while i < bytes.len() {
        if !is_token_byte(bytes[i]) {
            i += 1;
            continue;
        }
        let j = i + bytes[i..].iter().take_while(|&&b| is_token_byte(b)).count();
        if j - i >= 20 {
            out.push((i, j));
        }
        i = j;
    }
    out
}

/// `_card_spans` on the run `text[base..end]` (byte offsets).
fn card_spans(text: &str, base: usize, end: usize, out: &mut Vec<Span>) {
    let run = &text[base..end];
    // digit groups: (start, end) byte offsets in text; digit values
    let mut groups: Vec<(usize, usize)> = Vec::new();
    let mut digits: Vec<u32> = Vec::new();
    let mut starts: Vec<usize> = vec![0];
    let mut cur: Option<usize> = None;
    for (b, ch) in run.char_indices() {
        match decimal_value(ch) {
            Some(v) => {
                digits.push(v);
                if cur.is_none() {
                    cur = Some(base + b);
                }
            }
            None => {
                if let Some(s) = cur.take() {
                    groups.push((s, base + b));
                    starts.push(digits.len());
                }
            }
        }
    }
    if let Some(s) = cur.take() {
        groups.push((s, end));
        starts.push(digits.len());
    }
    let n = groups.len();
    if starts[n] < 13 {
        return;
    }
    let dbl: Vec<u32> = digits
        .iter()
        .map(|&d| if d > 4 { d * 2 - 9 } else { d * 2 })
        .collect();
    let mut c: [Vec<u32>; 2] = [vec![0], vec![0]];
    for (k, ck) in c.iter_mut().enumerate() {
        let mut acc = 0;
        for (i, &d) in digits.iter().enumerate() {
            acc += if i % 2 == k { dbl[i] } else { d };
            ck.push(acc);
        }
    }
    let first = out.len();
    let mut covered: Option<usize> = None; // end of the last span found
    let (mut lo, mut hi) = (0usize, 0usize);
    for i in 0..n {
        let s0 = starts[i];
        lo = lo.max(i);
        while lo < n && starts[lo + 1] - s0 < 13 {
            lo += 1;
        }
        while lo < n && covered.is_some_and(|cv| groups[lo].1 <= cv) {
            lo += 1;
        }
        hi = hi.max(lo);
        while hi < n && starts[hi + 1] - s0 <= 19 {
            hi += 1;
        }
        for j in lo..hi {
            let e = starts[j + 1];
            let ck = &c[e & 1];
            if (ck[e] - ck[s0]).is_multiple_of(10) {
                let (a0, b0) = (groups[i].0, groups[j].1);
                match covered {
                    Some(cv) if out.len() > first && a0 <= cv => {
                        let last = out.last_mut().expect("a span");
                        last.end = cv.max(b0);
                    }
                    _ => out.push(Span {
                        start: a0,
                        end: b0,
                        kind: "card",
                    }),
                }
                covered = Some(out.last().expect("a span").end);
            }
        }
    }
}

fn merge_secrets(mut found: Vec<Span>) -> Vec<Span> {
    found.sort_by_key(|s| (s.start, rank(s.kind))); // stable, as Python's sort
    let mut merged: Vec<Span> = Vec::with_capacity(found.len());
    for s in found {
        match merged.last_mut() {
            Some(prev) if s.start < prev.end => {
                if rank(s.kind) < rank(prev.kind) {
                    prev.kind = s.kind;
                }
                prev.end = prev.end.max(s.end);
            }
            _ => merged.push(s),
        }
    }
    merged
}

/// `find_secrets` on byte offsets.
fn secrets_bytes(text: &str) -> Vec<Span> {
    let mut found: Vec<Span> = Vec::new();
    for m in PEM.find_iter(text) {
        found.push(Span {
            start: m.start(),
            end: m.end(),
            kind: "pem",
        });
    }
    for (a, b) in find_where(&JWT, text, |s| no_word_before(text, s)) {
        found.push(Span {
            start: a,
            end: b,
            kind: "jwt",
        });
    }
    let api = find_where(&API_KEY, text, |s| {
        if text[s..].starts_with("Bearer") {
            no_word_before(text, s) // `\bBearer`; no other branch starts with B
        } else {
            !prev_char(text, s).is_some_and(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-')
        }
    });
    for (a, b) in api {
        found.push(Span {
            start: a,
            end: b,
            kind: "api_key",
        });
    }
    let mut at = 0;
    while at <= text.len() {
        let Some(caps) = ASSIGN.captures_at(text, at) else {
            break;
        };
        let m = caps.get(0).expect("group 0");
        if no_word_before(text, m.start()) {
            let g = caps
                .get(1)
                .or_else(|| caps.get(2))
                .or_else(|| caps.get(3))
                .expect("a value");
            found.push(Span {
                start: g.start(),
                end: g.end(),
                kind: "assignment",
            });
            at = m.end();
        } else {
            at = m.start() + next_char_len(text, m.start());
        }
    }
    for m in CARD_RUN.find_iter(text) {
        card_spans(text, m.start(), m.end(), &mut found);
    }
    for (a, b) in tokens(text) {
        if is_entropy_secret(&text.as_bytes()[a..b]) {
            found.push(Span {
                start: a,
                end: b,
                kind: "entropy",
            });
        }
    }
    merge_secrets(found)
}

/// Secret spans, sorted and non-overlapping (code points); see `redact.find_secrets`.
pub fn find_secrets(text: &str) -> Vec<Span> {
    let cp = Cp::new(text);
    secrets_bytes(text)
        .into_iter()
        .map(|s| cp.span(s))
        .collect()
}

// ---- protected entities --------------------------------------------------------------------

fn emoji_runs(text: &str, out: &mut Vec<Span>) {
    let chars: Vec<(usize, char)> = text.char_indices().collect();
    let n = chars.len();
    let mut i = 0;
    while i < n {
        if !is_emoji(chars[i].1) {
            i += 1;
            continue;
        }
        let mut j = i + 1;
        while j < n && (is_emoji(chars[j].1) || is_emoji_joiner(chars[j].1)) {
            j += 1;
        }
        while chars[j - 1].1 == ZWJ {
            j -= 1;
        }
        let end = if j < n { chars[j].0 } else { text.len() };
        out.push(Span {
            start: chars[i].0,
            end,
            kind: "emoji",
        });
        i = j;
    }
}

/// `find_protected` on byte offsets.
fn protected_bytes(text: &str) -> Vec<Span> {
    let mut found: Vec<Span> = text
        .char_indices()
        .filter(|&(_, c)| c == OBJECT)
        .map(|(b, c)| Span {
            start: b,
            end: b + c.len_utf8(),
            kind: "object",
        })
        .collect();
    for m in CODE.find_iter(text) {
        found.push(Span {
            start: m.start(),
            end: m.end(),
            kind: "code",
        });
    }
    for m in URL.find_iter(text) {
        found.push(Span {
            start: m.start(),
            end: m.end(),
            kind: "url",
        });
    }
    let mentions = find_where(&MENTION, text, |s| {
        text.as_bytes()[s] == b'<' || no_word_before(text, s)
    });
    for (a, b) in mentions {
        found.push(Span {
            start: a,
            end: b,
            kind: "mention",
        });
    }
    for m in EMOJI_NAME.find_iter(text) {
        found.push(Span {
            start: m.start(),
            end: m.end(),
            kind: "emoji",
        });
    }
    emoji_runs(text, &mut found);
    found.sort_by_key(|s| (s.start, std::cmp::Reverse(s.end))); // stable
    let mut merged: Vec<Span> = Vec::with_capacity(found.len());
    for s in found {
        match merged.last_mut() {
            Some(last) if s.start < last.end => last.end = last.end.max(s.end),
            _ => merged.push(s),
        }
    }
    merged
}

/// Protected spans, sorted and non-overlapping (code points); see `entities.find_protected`.
pub fn find_protected(text: &str) -> Vec<Span> {
    let cp = Cp::new(text);
    protected_bytes(text)
        .into_iter()
        .map(|s| cp.span(s))
        .collect()
}

// ---- shield / unshield ---------------------------------------------------------------------

/// `redact.shield`: secrets become `[[GLANCE_S<n>]]`, other protected spans `[[GLANCE_E<n>]]`.
pub fn shield(text: &str) -> Shielded {
    let cp = Cp::new(text);
    let secrets = secrets_bytes(text);
    let entities = protected_bytes(text);
    let mut items: Vec<(usize, usize, char)> =
        secrets.iter().map(|s| (s.start, s.end, 'S')).collect();
    // Both lists are sorted and non-overlapping: drop the entities touching a secret.
    let mut k = 0;
    for e in &entities {
        while k < secrets.len() && secrets[k].end <= e.start {
            k += 1;
        }
        if !(k < secrets.len() && secrets[k].start < e.end) {
            items.push((e.start, e.end, 'E'));
        }
    }
    items.sort_unstable();
    let (mut ns, mut ne) = (0usize, 0usize);
    let mut out = String::with_capacity(text.len() + 16 * items.len());
    let mut mapping = Vec::with_capacity(items.len());
    let mut segments = Vec::with_capacity(2 * items.len() + 1);
    let (mut pos, mut cur) = (0usize, 0usize); // original byte offset, shielded code points
    for (a, b, tag) in items {
        if a > pos {
            out.push_str(&text[pos..a]);
            let (p0, a0) = (cp.at(pos), cp.at(a));
            segments.push((cur, cur + a0 - p0, p0, a0, false));
            cur += a0 - p0;
        }
        let n = if tag == 'S' {
            ns += 1;
            ns
        } else {
            ne += 1;
            ne
        };
        let ph = format!("[[GLANCE_{tag}{n}]]");
        out.push_str(&ph);
        segments.push((cur, cur + ph.len(), cp.at(a), cp.at(b), true));
        cur += ph.len();
        mapping.push((ph, text[a..b].to_owned()));
        pos = b;
    }
    if pos < text.len() {
        out.push_str(&text[pos..]);
        let (p0, n0) = (cp.at(pos), cp.at(text.len()));
        segments.push((cur, cur + n0 - p0, p0, n0, false));
    }
    Shielded {
        text: out,
        mapping,
        has_objects: text.contains(OBJECT),
        segments,
    }
}

/// `redact.unshield`: None unless every placeholder occurs once, in order, none invented.
pub fn unshield(text: &str, mapping: &[(String, String)]) -> Option<String> {
    if text.matches(PLACEHOLDER_OPEN).count() != mapping.len() {
        return None;
    }
    let mut found = Vec::with_capacity(mapping.len());
    let mut last: Option<usize> = None;
    for (ph, _) in mapping {
        let mut it = text.match_indices(ph.as_str());
        let (i, _) = it.next()?;
        if it.next().is_some() || last.is_some_and(|l| i < l) {
            return None;
        }
        last = Some(i);
        found.push(i);
    }
    // Every `[[GLANCE_` is one of the placeholders, so replacing them in place is the
    // single pass Python's re.sub makes.
    let mut out = String::with_capacity(text.len());
    let mut pos = 0;
    for ((ph, orig), i) in mapping.iter().zip(found) {
        out.push_str(&text[pos..i]);
        out.push_str(orig);
        pos = i + ph.len();
    }
    out.push_str(&text[pos..]);
    Some(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn kinds(t: &str) -> Vec<(String, &'static str)> {
        let chars: Vec<char> = t.chars().collect();
        find_secrets(t)
            .into_iter()
            .map(|s| (chars[s.start..s.end].iter().collect(), s.kind))
            .collect()
    }

    #[test]
    fn secret_kinds() {
        let key = format!("sk-ant-api03-{}", "a1B2".repeat(12));
        assert_eq!(kinds(&format!("use {key} for it")), vec![(key, "api_key")]);
        let hex = "9f8a7b6c5d4e3f2a1b0c9d8e7f6a5b4c";
        assert_eq!(
            kinds(&format!("use {hex} x")),
            vec![(hex.to_owned(), "entropy")]
        );
        assert_eq!(kinds("pay 4111 1111 1111 1111 now")[0].1, "card");
        assert_eq!(
            kinds("my password: hunter2 ok"),
            vec![("hunter2".to_owned(), "assignment")]
        );
        assert!(kinds("internationalization-and-localization").is_empty());
    }

    #[test]
    fn python_word_boundaries_and_ignorecase() {
        // `ı` matches `i` under Python's IGNORECASE; a word char before blocks `\b`.
        assert_eq!(kinds("apı_key=abc"), vec![("abc".to_owned(), "assignment")]);
        assert!(kinds("xpassword=abc").is_empty());
        // Bangla vowel sign (Mc) is not Python `\w`, so `\b` holds after it.
        assert_eq!(kinds("কা password=abc").len(), 1);
    }

    #[test]
    fn bangla_digits_are_card_digits() {
        let ascii = "4111111111111111";
        let bangla: String = ascii
            .chars()
            .map(|c| char::from_u32(0x09E6 + c.to_digit(10).unwrap()).unwrap())
            .collect();
        assert_eq!(kinds(&bangla), vec![(bangla.clone(), "card")]);
    }

    #[test]
    fn protected_and_code_points() {
        let t = "\u{1F600}\u{1F600} x @sam";
        assert_eq!(
            find_protected(t).last(),
            Some(&Span {
                start: 5,
                end: 9,
                kind: "mention"
            })
        );
        assert!(find_protected("C# and a#b are fine").is_empty());
        assert_eq!(find_protected("ok \u{1F468}\u{200D}\u{1F469} ok").len(), 1);
    }

    #[test]
    fn shield_round_trip() {
        let t = format!(
            "hey @sam use sk-ant-api03-{} see https://x.test/p é",
            "a1B2".repeat(12)
        );
        let s = shield(&t);
        assert_eq!(s.text.matches(PLACEHOLDER_OPEN).count(), 3);
        assert_eq!(unshield(&s.text, &s.mapping).as_deref(), Some(t.as_str()));
        assert_eq!(unshield("nothing", &s.mapping), None);
    }

    #[test]
    fn compensated_sum_matches_cpython() {
        assert_eq!(sum_floats(true, [0.1, 0.2, 0.3].into_iter()), 0.6);
        assert_eq!(
            sum_floats(false, [0.1, 0.2, 0.3].into_iter()),
            0.6000000000000001
        );
    }
}
